  private final List<ContextUnit> lazyUnits = new ArrayList<>();
  private final Map<String, List<Candidate>> eagerCandidates = new LinkedHashMap<>();
  private final Map<ProbeKey, Optional<Candidate>> lazyProbeResults = new HashMap<>();
  private final Map<String, Selection> selections = new HashMap<>();
  private final Map<String, StructClass> classes = new HashMap<>();
  private final Map<String, String> badlyPlacedClasses = new HashMap<>();
  private final Map<String, ContextUnit> familyAnchors = new HashMap<>();
  private final Map<String, List<String>> abstractNames = new HashMap<>();
  private int nextOriginId;
  private FamilyIndex familyIndex;

  private final PluginContext pluginContext = new PluginContext();

  @SuppressWarnings("deprecation")
  public StructContext(IBytecodeProvider legacyProvider, IResultSaver saver, IDecompiledData decompiledData) {
    this(legacyProvider, saver, decompiledData, DuplicateClassStrategy.FIRST);
  }

  @SuppressWarnings("deprecation")
  public StructContext(
    IBytecodeProvider legacyProvider,
    IResultSaver saver,
    IDecompiledData decompiledData,
    DuplicateClassStrategy duplicateClassStrategy
  ) {
    this.legacyProvider = legacyProvider;
    this.saver = saver;
    this.decompiledData = decompiledData;
    this.duplicateClassStrategy = Objects.requireNonNull(duplicateClassStrategy);
  }

  public StructContext(IResultSaver saver, IDecompiledData decompiledData) {
    this(null, saver, decompiledData, DuplicateClassStrategy.FIRST);
  }

  public @Nullable StructClass getClass(String name) {
    if (name == null) {
      return null;
    }

    synchronized (this.resolutionLock) {
      StructClass cached = this.classes.get(name);
      if (cached != null) {
        return cached == getSentinel() ? null : cached;
      }

      Selection selection = this.resolveSelection(name);
      if (selection == null) {
        this.classes.put(name, getSentinel());
        return null;
      }

      DecompilerContext.getLogger().writeMessage(
        "Loading Class: " + name + " from " + selection.candidate.unit.getOriginDescription(),
        IFernflowerLogger.Severity.INFO
      );
      StructClass clazz = selection.candidate.getStructClass();
      this.classes.put(name, clazz);

      if (!name.equals(clazz.qualifiedName)) {
        this.badlyPlacedClasses.put(name, clazz.qualifiedName);
        this.classes.put(clazz.qualifiedName, clazz);
        this.classes.remove(name);
      }

      return clazz;
    }
  }

  public boolean hasClass(final String name) {
    if (name == null) {
      return false;
    }

    synchronized (this.resolutionLock) {
      return this.resolveSelection(name) != null;
    }
  }

  public List<StructClass> getOwnClasses() {
    synchronized (this.resolutionLock) {
      List<StructClass> ownClasses = new ArrayList<>();
      Set<String> seen = new LinkedHashSet<>();
      for (Map.Entry<String, List<Candidate>> entry : this.eagerCandidates.entrySet()) {
        if (!seen.add(entry.getKey()) || entry.getValue().stream().noneMatch(candidate -> candidate.unit.isOwn())) {
          continue;
        }

        Selection selection = this.resolveSelection(entry.getKey());
        if (selection != null && selection.candidate.unit.isOwn()) {
          ownClasses.add(Objects.requireNonNull(this.getClass(entry.getKey()), () -> "Could not find class " + entry.getKey()));
        }
      }
      return List.copyOf(ownClasses);
    }
  }

  public void reloadContext() throws IOException {
    synchronized (this.resolutionLock) {
      final List<ContextUnit> roots = this.units.stream().filter(ContextUnit::isRoot).toList();
      this.units.clear();
      this.lazyUnits.clear();
      this.eagerCandidates.clear();
      this.lazyProbeResults.clear();
      this.abstractNames.clear();
      this.invalidateDecisions();

      for (ContextUnit unit : roots) {
        unit.clear();
        this.registerUnit(unit);
      }
    }
  }

  public void saveContext() {
    for (ContextUnit unit : List.copyOf(this.units)) {
      if (unit.isOwn()) {
        try {
          unit.save(this::getClass, name -> this.isSelectedOrigin(name, unit));
        } catch (final IOException ex) {
          DecompilerContext.getLogger().writeMessage("Failed to save data for context unit " + unit.getName(), IFernflowerLogger.Severity.ERROR, ex);
        }
      }
    }
  }

  private boolean isSelectedOrigin(String name, ContextUnit unit) {
    synchronized (this.resolutionLock) {
      Selection selection = this.resolveSelection(name);
      return selection != null && selection.candidate.unit == unit;
    }
  }

  private static boolean isJarFile(File file) {
    if (!file.isFile()) return false;
    String name = file.getName();
    if (name.endsWith(".jar") || name.endsWith(".zip")) return true;
    if (name.endsWith(".class")) return false;
    try (SeekableByteChannel channel = Files.newByteChannel(file.toPath())) {
      long size = channel.size();
      if (size < 22) return false;
      int bufferSize = (int) Math.min(size & ~3, 1024);
      channel.position(size - bufferSize);
      ByteBuffer buffer = ByteBuffer.allocate(bufferSize).order(ByteOrder.LITTLE_ENDIAN);
      int read = 0;
      while (read < bufferSize) {
        read += channel.read(buffer);
      }
      buffer.flip();
      for (int pos = buffer.limit() - 22; pos >= 0; pos--) {
        if (buffer.getInt(pos) == 0x06054b50) {
          return true;
        }
      }
    } catch (IOException e) {
      DecompilerContext.getLogger().writeMessage("Could not determine if " + file + " contains a JAR file", IFernflowerLogger.Severity.WARN, e);
    }
    return false;
  }

  public void addSpace(File file, boolean isOwn) {
    if (file.isDirectory()) {
      addSpace(new DirectoryContextSource(this.legacyProvider, file), isOwn);
    } else if (isJarFile(file)) {
      try {
        addSpace(new JarContextSource(this.legacyProvider, file), isOwn);
      } catch (final IOException ex) {
        final String message = "Invalid archive " + file;
        DecompilerContext.getLogger().writeMessage(message, IFernflowerLogger.Severity.ERROR, ex);
        throw new UncheckedIOException(message, ex);
      }
    } else {
      try {
        addSpace(new SingleFileContextSource(this.legacyProvider, file), isOwn);
      } catch (final IOException ex) {
        final String message = "Invalid file " + file;
        DecompilerContext.getLogger().writeMessage(message, IFernflowerLogger.Severity.ERROR, ex);
        throw new UncheckedIOException(message, ex);
      }
    }
  }

  public void addSpace(final IContextSource source, final boolean isOwn) {
    synchronized (this.resolutionLock) {
      this.registerSource(source, isOwn, true);
      this.invalidateDecisions();
    }
  }

  private void registerSource(final IContextSource source, final boolean isOwn, final boolean isRoot) {
    ContextUnit unit = new ContextUnit(source, isOwn, isRoot, this.nextOriginId++, this.saver, this.decompiledData);
    this.registerUnit(unit);
  }

  private void registerUnit(final ContextUnit unit) {
    this.units.add(unit);
    if (unit.isLazy()) {
      this.lazyUnits.add(unit);
    }

    DecompilerContext.getLogger().writeMessage("Scanning classes from " + unit.getOriginDescription(), IFernflowerLogger.Severity.INFO);
    for (String className : unit.getClassNames()) {
      List<Candidate> candidates = this.eagerCandidates.computeIfAbsent(className, ignored -> new ArrayList<>());
      if (candidates.stream().noneMatch(candidate -> candidate.unit == unit)) {
        candidates.add(new Candidate(unit, className, null));
      }
      DecompilerContext.getLogger().writeMessage("    " + className, IFernflowerLogger.Severity.TRACE);
    }

    for (IContextSource child : unit.getChildContexts()) {
      this.registerSource(child, unit.isOwn(), false);
    }
  }

  public PluginContext getPluginContext() {
    return this.pluginContext;
  }

  private Selection resolveSelection(String name) {
    Selection cached = this.selections.get(name);
    if (cached != null) {
      return cached;
    }

    List<Candidate> candidates = this.findHighestTierCandidates(name);
    if (candidates.isEmpty()) {
      return null;
    }

    boolean differing = candidatesDiffer(candidates);
    if (this.duplicateClassStrategy == DuplicateClassStrategy.ERROR && differing) {
      String message = "Duplicate class conflict for " + name + " with strategy error; conflicting highest-tier origins: " +
        joinOrigins(candidates);
      DecompilerContext.getLogger().writeMessage(message, IFernflowerLogger.Severity.ERROR);
      throw new IllegalStateException(message);
    }

    Candidate selected = switch (this.duplicateClassStrategy) {
      case FIRST, ERROR -> candidates.get(0);
      case LAST -> candidates.get(candidates.size() - 1);
    };
    String familyRoot = name;

    if (selected.unit.isOwn()) {
      FamilyIndex index = this.getFamilyIndex();
      familyRoot = index.familyRoot(name);
      if (index.isActive(familyRoot)) {
        ContextUnit anchor = this.familyAnchors.get(familyRoot);
        if (anchor == null) {
          List<Candidate> rootCandidates = this.ownCandidates(familyRoot);
          if (!rootCandidates.isEmpty()) {
            if (familyRoot.equals(name)) {
              anchor = selected.unit;
            } else {
              anchor = Objects.requireNonNull(this.resolveSelection(familyRoot)).candidate.unit;
            }
          } else {
            String anchorDuplicate = index.anchorDuplicate(familyRoot);
            if (name.equals(anchorDuplicate)) {
              anchor = selected.unit;
            } else {
              anchor = Objects.requireNonNull(this.resolveSelection(anchorDuplicate)).candidate.unit;
            }
          }
          this.familyAnchors.put(familyRoot, anchor);
        }

        ContextUnit finalAnchor = anchor;
        Candidate anchoredCandidate = candidates.stream()
          .filter(candidate -> candidate.unit == finalAnchor)
          .findFirst()
          .orElse(null);
        if (anchoredCandidate == null) {
          String alternatives = joinOrigins(candidates);
          String message = "Class family origin conflict: family root " + familyRoot + ", member " + name +
            ", anchored origin " + anchor.getOriginDescription() + ", alternative origins: " + alternatives;
          DecompilerContext.getLogger().writeMessage(message, IFernflowerLogger.Severity.ERROR);
          throw new IllegalStateException(message);
        }
        selected = anchoredCandidate;
      }
    }

    Selection selection = new Selection(selected, familyRoot);
    this.selections.put(name, selection);
    this.logDuplicateDecision(name, candidates, selection, differing);
    return selection;
  }

  private List<Candidate> findHighestTierCandidates(String name) {
    List<Candidate> eager = this.eagerCandidates.getOrDefault(name, List.of());
    List<Candidate> own = eager.stream().filter(candidate -> candidate.unit.isOwn()).toList();
    if (!own.isEmpty()) {
      return own;
    }

    List<Candidate> libraries = new ArrayList<>();
    for (Candidate candidate : eager) {
      if (!candidate.unit.isOwn()) {
        libraries.add(candidate);
      }
    }
    for (ContextUnit unit : this.lazyUnits) {
      Candidate candidate = this.probeLazy(unit, name);
      if (candidate != null && libraries.stream().noneMatch(existing -> existing.unit == unit)) {
        libraries.add(candidate);
      }
    }
    return libraries;
  }

  private Candidate probeLazy(ContextUnit unit, String name) {
    ProbeKey key = new ProbeKey(unit, name);
    Optional<Candidate> cached = this.lazyProbeResults.get(key);
    if (cached != null) {
      return cached.orElse(null);
    }

    try {
      byte[] bytes = unit.getClassBytes(name);
      Candidate candidate = bytes == null ? null : new Candidate(unit, name, bytes);
      this.lazyProbeResults.put(key, Optional.ofNullable(candidate));
      return candidate;
    } catch (IOException ex) {
      DecompilerContext.getLogger().writeMessage(
        "Failed to probe class " + name + " in " + unit.getOriginDescription(),
        IFernflowerLogger.Severity.ERROR,
        ex
      );
      this.lazyProbeResults.put(key, Optional.empty());
      return null;
    }
  }

  private List<Candidate> ownCandidates(String name) {
    return this.eagerCandidates.getOrDefault(name, List.of()).stream()
      .filter(candidate -> candidate.unit.isOwn())
      .toList();
  }

  private FamilyIndex getFamilyIndex() {
    if (this.familyIndex != null) {
      return this.familyIndex;
    }

    Map<String, LinkedHashSet<String>> parents = new LinkedHashMap<>();
    LinkedHashSet<String> duplicateNames = new LinkedHashSet<>();
    for (Map.Entry<String, List<Candidate>> entry : this.eagerCandidates.entrySet()) {
      List<Candidate> own = entry.getValue().stream().filter(candidate -> candidate.unit.isOwn()).toList();
      if (own.size() > 1) {
        duplicateNames.add(entry.getKey());
      }
      for (Candidate candidate : own) {
        StructClass clazz = candidate.getStructClass();
        StructInnerClassesAttribute innerClasses = clazz.getAttribute(StructGeneralAttribute.ATTRIBUTE_INNER_CLASSES);
        if (innerClasses != null) {
          for (StructInnerClassesAttribute.Entry inner : innerClasses.getEntries()) {
            if (inner.enclosingName != null && !inner.innerName.equals(inner.enclosingName)) {
              parents.computeIfAbsent(inner.innerName, ignored -> new LinkedHashSet<>()).add(inner.enclosingName);
            }
          }
        }

        StructEnclosingMethodAttribute enclosingMethod = clazz.getAttribute(StructGeneralAttribute.ATTRIBUTE_ENCLOSING_METHOD);
        if (enclosingMethod != null && !clazz.qualifiedName.equals(enclosingMethod.getClassName())) {
          parents.computeIfAbsent(clazz.qualifiedName, ignored -> new LinkedHashSet<>()).add(enclosingMethod.getClassName());
        }
      }
    }

    Map<String, String> roots = new HashMap<>();
    LinkedHashSet<String> activeRoots = new LinkedHashSet<>();
    Map<String, String> anchorDuplicates = new HashMap<>();
    for (String duplicateName : duplicateNames) {
      String root = findFamilyRoot(duplicateName, parents, roots);
      activeRoots.add(root);
      anchorDuplicates.putIfAbsent(root, duplicateName);
    }
    this.familyIndex = new FamilyIndex(parents, roots, activeRoots, anchorDuplicates);
    return this.familyIndex;
  }

  private static String findFamilyRoot(
    String name,
    Map<String, LinkedHashSet<String>> parents,
    Map<String, String> roots
  ) {
    String cached = roots.get(name);
    if (cached != null) {
      return cached;
    }

    LinkedHashSet<String> path = new LinkedHashSet<>();
    String current = name;
    while (path.add(current)) {
      LinkedHashSet<String> directParents = parents.get(current);
      if (directParents == null || directParents.isEmpty()) {
        break;
      }
      current = directParents.iterator().next();
    }
    for (String member : path) {
      roots.put(member, current);
    }
    return current;
  }

  private static boolean candidatesDiffer(List<Candidate> candidates) {
    if (candidates.size() < 2) {
      return false;
    }
    byte[] first = candidates.get(0).getBytes();
    for (int index = 1; index < candidates.size(); index++) {
      if (!Arrays.equals(first, candidates.get(index).getBytes())) {
        return true;
      }
    }
    return false;
  }

  private void logDuplicateDecision(String name, List<Candidate> candidates, Selection selection, boolean differing) {
    if (candidates.size() < 2) {
      return;
    }

    List<String> ignored = candidates.stream()
      .filter(candidate -> candidate != selection.candidate)
      .map(candidate -> candidate.unit.getOriginDescription())
      .toList();
    String message = "Duplicate class decision: binary name " + name + ", strategy " + this.duplicateClassStrategy +
      ", selected origin " + selection.candidate.unit.getOriginDescription() + ", ignored origins: " + ignored +
      ", metadata family root " + selection.familyRoot;
    DecompilerContext.getLogger().writeMessage(
      message,
      differing ? IFernflowerLogger.Severity.WARN : IFernflowerLogger.Severity.INFO
    );
  }

  private static String joinOrigins(List<Candidate> candidates) {
    return candidates.stream()
      .map(candidate -> candidate.unit.getOriginDescription())
      .collect(Collectors.joining(", "));
  }

  private void invalidateDecisions() {
    this.classes.clear();
    this.badlyPlacedClasses.clear();
    this.selections.clear();
    this.familyAnchors.clear();
    this.familyIndex = null;
  }

  private static final class Candidate {
    private final ContextUnit unit;
    private final String className;
    private byte[] bytes;
    private StructClass structClass;

    private Candidate(ContextUnit unit, String className, byte[] bytes) {
      this.unit = unit;
      this.className = className;
      this.bytes = bytes;
    }

    private byte[] getBytes() {
      if (this.bytes == null) {
        try {
          this.bytes = this.unit.getClassBytes(this.className);
        } catch (IOException ex) {
          throw new UncheckedIOException(
            "Failed to read class " + this.className + " from " + this.unit.getOriginDescription(),
            ex
          );
        }
        if (this.bytes == null) {
          throw new IllegalStateException(
            "Context origin " + this.unit.getOriginDescription() + " listed class " + this.className + " but did not provide its bytes"
          );
        }
      }
      return this.bytes;
    }

    private StructClass getStructClass() {
      if (this.structClass == null) {
        try {
          this.structClass = StructClass.create(new DataInputFullStream(this.getBytes()), this.unit.isOwn());
        } catch (IOException ex) {
          throw new UncheckedIOException(
            "Failed to parse class " + this.className + " from " + this.unit.getOriginDescription(),
            ex
          );
        }
      }
      return this.structClass;
    }
  }

  private record ProbeKey(ContextUnit unit, String className) { }

  private record Selection(Candidate candidate, String familyRoot) { }

  private static final class FamilyIndex {
    private final Map<String, LinkedHashSet<String>> parents;
    private final Map<String, String> roots;
    private final Set<String> activeRoots;
    private final Map<String, String> anchorDuplicates;

    private FamilyIndex(
      Map<String, LinkedHashSet<String>> parents,
      Map<String, String> roots,
      Set<String> activeRoots,
      Map<String, String> anchorDuplicates
    ) {
      this.parents = parents;
      this.roots = roots;
      this.activeRoots = activeRoots;
      this.anchorDuplicates = anchorDuplicates;
    }

    private String familyRoot(String name) {
      return findFamilyRoot(name, this.parents, this.roots);
    }

    private boolean isActive(String root) {
      return this.activeRoots.contains(root);
    }

    private String anchorDuplicate(String root) {
      return Objects.requireNonNull(this.anchorDuplicates.get(root));
    }
  }

