    properties.put(IFernflowerPreferences.THREADS, "1");
    DecompilerContext.setCurrentContext(new DecompilerContext(
      properties,
      new CollectingLogger(),
      context,
      new ClassesProcessor(context),
      null
    ));
    return context;
  }

  private Map<String, byte[]> compile(String name, Map<String, String> sources) throws IOException {
    Path sourceRoot = tempDir.resolve(name).resolve("src");
    Path outputRoot = tempDir.resolve(name).resolve("classes");
    Files.createDirectories(outputRoot);
    List<String> arguments = new ArrayList<>(List.of("-g:none", "-d", outputRoot.toString()));
    for (Map.Entry<String, String> source : sources.entrySet()) {
      Path sourceFile = sourceRoot.resolve(source.getKey());
      Files.createDirectories(sourceFile.getParent());
      Files.writeString(sourceFile, source.getValue(), StandardCharsets.UTF_8);
      arguments.add(sourceFile.toString());
    }

    JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
    assertNotNull(compiler);
    assertEquals(0, compiler.run(null, null, null, arguments.toArray(String[]::new)));

    Map<String, byte[]> classes = new LinkedHashMap<>();
    try (var paths = Files.walk(outputRoot)) {
      for (Path classFile : paths.filter(path -> path.toString().endsWith(".class")).sorted().toList()) {
        String relative = outputRoot.relativize(classFile).toString().replace(classFile.getFileSystem().getSeparator(), "/");
        classes.put(relative.substring(0, relative.length() - IContextSource.CLASS_SUFFIX.length()), Files.readAllBytes(classFile));
      }
    }
    return classes;
  }

  private static Map<String, byte[]> only(Map<String, byte[]> classes, String... names) {
    Map<String, byte[]> selected = new LinkedHashMap<>();
    for (String name : names) {
      selected.put(name, classes.get(name));
    }
    return selected;
  }

  private static class MemorySource implements IContextSource {
    private final String name;
    private final Map<String, byte[]> classes;
    private final List<String> others;
    private final List<String> emittedClasses = new ArrayList<>();
    private final List<String> emittedOthers = new ArrayList<>();

    private MemorySource(String name, Map<String, byte[]> classes) {
      this(name, classes, List.of());
    }

    private MemorySource(String name, Map<String, byte[]> classes, List<String> others) {
      this.name = name;
      this.classes = new LinkedHashMap<>(classes);
      this.others = List.copyOf(others);
    }

    @Override
    public String getName() {
      return this.name;
    }

    @Override
    public Entries getEntries() {
      return new Entries(
        this.classes.keySet().stream().map(Entry::atBase).toList(),
        List.of(),
        this.others.stream().map(Entry::atBase).toList()
      );
    }

    @Override
    public byte[] getClassBytes(String className) {
      return this.classes.get(className);
    }

    @Override
    public InputStream getInputStream(String resource) {
      if (resource.endsWith(CLASS_SUFFIX)) {
        byte[] bytes = this.classes.get(resource.substring(0, resource.length() - CLASS_SUFFIX.length()));
        return bytes == null ? null : new ByteArrayInputStream(bytes);
      }
      return this.others.contains(resource) ? new ByteArrayInputStream(resource.getBytes(StandardCharsets.UTF_8)) : null;
    }

    @Override
    public IOutputSink createOutputSink(IResultSaver saver) {
      return new IOutputSink() {
        @Override
        public void begin() { }

        @Override
        public void acceptClass(String qualifiedName, String fileName, String content, int[] mapping) {
          emittedClasses.add(qualifiedName);
        }

        @Override
        public void acceptDirectory(String directory) { }

        @Override
        public void acceptOther(String path) {
          emittedOthers.add(path);
        }

        @Override
        public void close() { }
      };
    }
  }

  private static class SimpleData implements IDecompiledData {
    @Override
    public String getClassEntryName(StructClass cl, String entryname) {
      return entryname + ".java";
    }

    @Override
    public void processClass(StructClass cl) { }

    @Override
    public String getClassContent(StructClass cl) {
      return cl.qualifiedName;
    }
  }

  private static class CollectingLogger extends IFernflowerLogger {
    private final List<String> messages = new ArrayList<>();

    @Override
    public void writeMessage(String message, Severity severity) {
      this.messages.add(severity + ": " + message);
    }

    @Override
    public void writeMessage(String message, Severity severity, Throwable throwable) {
      this.messages.add(severity + ": " + message + ": " + throwable);
    }
  }
}
