   118	  public @Nullable StructClass getClass(String name) {
   119	    if (name == null) {
   120	      return null;
   121	    }
   122	
   123	    synchronized (this.resolutionLock) {
   124	      StructClass cached = this.classes.get(name);
   125	      if (cached != null) {
   126	        return cached == getSentinel() ? null : cached;
   127	      }
   128	
   129	      Selection selection = this.resolveSelection(name);
   130	      if (selection == null) {
   131	        this.classes.put(name, getSentinel());
   132	        return null;
   133	      }
   134	
   135	      DecompilerContext.getLogger().writeMessage(
   136	        "Loading Class: " + name + " from " + selection.candidate.unit.getOriginDescription(),
   137	        IFernflowerLogger.Severity.INFO
   138	      );
   139	      StructClass clazz = selection.candidate.getStructClass();
   140	      this.classes.put(name, clazz);
   141	
   142	      if (!name.equals(clazz.qualifiedName)) {
   143	        this.classes.put(clazz.qualifiedName, clazz);
   144	        this.classes.remove(name);
   145	      }
   146	
   147	      return clazz;
   148	    }
   149	  }
