   164	      Set<String> seen = new LinkedHashSet<>();
   165	      for (Map.Entry<String, List<Candidate>> entry : this.eagerCandidates.entrySet()) {
   166	        if (!seen.add(entry.getKey()) || entry.getValue().stream().noneMatch(candidate -> candidate.unit.isOwn())) {
   167	          continue;
