   300	  private Selection resolveSelection(String name) {
   301	    Selection cached = this.selections.get(name);
   302	    if (cached != null) {
   303	      return cached;
   304	    }
   305	
   306	    List<Candidate> candidates = this.findHighestTierCandidates(name);
   307	    if (candidates.isEmpty()) {
   308	      return null;
   309	    }
   310	
   311	    boolean differing = candidatesDiffer(candidates);
   312	    if (this.duplicateClassStrategy == DuplicateClassStrategy.ERROR && differing) {
   313	      String message = "Duplicate class conflict for " + name + " with strategy error; conflicting highest-tier origins: " +
   314	        joinOrigins(candidates);
   315	      DecompilerContext.getLogger().writeMessage(message, IFernflowerLogger.Severity.ERROR);
   316	      throw new IllegalStateException(message);
   317	    }
   318	
   319	    Candidate selected = switch (this.duplicateClassStrategy) {
   320	      case FIRST, ERROR -> candidates.get(0);
   321	      case LAST -> candidates.get(candidates.size() - 1);
   322	    };
   323	    String familyRoot = name;
   324	
   325	    if (selected.unit.isOwn()) {
   326	      FamilyIndex index = this.getFamilyIndex();
   327	      familyRoot = index.familyRoot(name);
   328	      if (index.isActive(familyRoot)) {
   329	        ContextUnit anchor = this.familyAnchors.get(familyRoot);
   330	        if (anchor == null) {
   331	          List<Candidate> rootCandidates = this.ownCandidates(familyRoot);
   332	          if (!rootCandidates.isEmpty()) {
   333	            if (familyRoot.equals(name)) {
   334	              anchor = selected.unit;
   335	            } else {
   336	              anchor = Objects.requireNonNull(this.resolveSelection(familyRoot)).candidate.unit;
   337	            }
   338	          } else {
   339	            String anchorDuplicate = index.anchorDuplicate(familyRoot);
   340	            if (name.equals(anchorDuplicate)) {
   341	              anchor = selected.unit;
   342	            } else {
   343	              anchor = Objects.requireNonNull(this.resolveSelection(anchorDuplicate)).candidate.unit;
   344	            }
   345	          }
   346	          this.familyAnchors.put(familyRoot, anchor);
   347	        }
   348	
   349	        ContextUnit finalAnchor = anchor;
   350	        Candidate anchoredCandidate = candidates.stream()
   351	          .filter(candidate -> candidate.unit == finalAnchor)
   352	          .findFirst()
   353	          .orElse(null);
   354	        if (anchoredCandidate == null) {
   355	          String alternatives = joinOrigins(candidates);
   356	          String message = "Class family origin conflict: family root " + familyRoot + ", member " + name +
   357	            ", anchored origin " + anchor.getOriginDescription() + ", alternative origins: " + alternatives;
   358	          DecompilerContext.getLogger().writeMessage(message, IFernflowerLogger.Severity.ERROR);
   359	          throw new IllegalStateException(message);
   360	        }
   361	        selected = anchoredCandidate;
   362	      }
   363	    }
   364	
   365	    Selection selection = new Selection(selected, familyRoot);
   366	    this.selections.put(name, selection);
   367	    this.logDuplicateDecision(name, candidates, selection, differing);
   368	    return selection;
   369	  }
