   371	  private List<Candidate> findHighestTierCandidates(String name) {
   372	    List<Candidate> eager = this.eagerCandidates.getOrDefault(name, List.of());
   373	    List<Candidate> own = eager.stream().filter(candidate -> candidate.unit.isOwn()).toList();
   374	    if (!own.isEmpty()) {
   375	      return own;
   376	    }
   377	
   378	    List<Candidate> libraries = new ArrayList<>();
   379	    for (Candidate candidate : eager) {
   380	      if (!candidate.unit.isOwn()) {
   381	        libraries.add(candidate);
   382	      }
   383	    }
   384	    for (ContextUnit unit : this.lazyUnits) {
   385	      Candidate candidate = this.probeLazy(unit, name);
   386	      if (candidate != null && libraries.stream().noneMatch(existing -> existing.unit == unit)) {
   387	        libraries.add(candidate);
   388	      }
   389	    }
   390	    return libraries;
   391	  }
   392	
   393	  private Candidate probeLazy(ContextUnit unit, String name) {
   394	    ProbeKey key = new ProbeKey(unit, name);
   395	    Optional<Candidate> cached = this.lazyProbeResults.get(key);
   396	    if (cached != null) {
   397	      return cached.orElse(null);
   398	    }
   399	
   400	    try {
   401	      byte[] bytes = unit.getClassBytes(name);
   402	      Candidate candidate = bytes == null ? null : new Candidate(unit, name, bytes);
   403	      this.lazyProbeResults.put(key, Optional.ofNullable(candidate));
   404	      return candidate;
   405	    } catch (IOException ex) {
   406	      DecompilerContext.getLogger().writeMessage(
   407	        "Failed to probe class " + name + " in " + unit.getOriginDescription(),
   408	        IFernflowerLogger.Severity.ERROR,
   409	        ex
   410	      );
   411	      this.lazyProbeResults.put(key, Optional.empty());
   412	      return null;
   413	    }
   414	  }
