   422	  private FamilyIndex getFamilyIndex() {
   423	    if (this.familyIndex != null) {
   424	      return this.familyIndex;
   425	    }
   426	
   427	    Map<String, LinkedHashSet<String>> parents = new LinkedHashMap<>();
   428	    LinkedHashSet<String> duplicateNames = new LinkedHashSet<>();
   429	    for (Map.Entry<String, List<Candidate>> entry : this.eagerCandidates.entrySet()) {
   430	      List<Candidate> own = entry.getValue().stream().filter(candidate -> candidate.unit.isOwn()).toList();
   431	      if (own.size() > 1) {
   432	        duplicateNames.add(entry.getKey());
   433	      }
   434	      for (Candidate candidate : own) {
   435	        StructClass clazz = candidate.getStructClass();
   436	        StructInnerClassesAttribute innerClasses = clazz.getAttribute(StructGeneralAttribute.ATTRIBUTE_INNER_CLASSES);
   437	        if (innerClasses != null) {
   438	          for (StructInnerClassesAttribute.Entry inner : innerClasses.getEntries()) {
   439	            if (inner.enclosingName != null && !inner.innerName.equals(inner.enclosingName)) {
   440	              parents.computeIfAbsent(inner.innerName, ignored -> new LinkedHashSet<>()).add(inner.enclosingName);
   441	            }
   442	          }
   443	        }
   444	
   445	        StructEnclosingMethodAttribute enclosingMethod = clazz.getAttribute(StructGeneralAttribute.ATTRIBUTE_ENCLOSING_METHOD);
   446	        if (enclosingMethod != null && !clazz.qualifiedName.equals(enclosingMethod.getClassName())) {
   447	          parents.computeIfAbsent(clazz.qualifiedName, ignored -> new LinkedHashSet<>()).add(enclosingMethod.getClassName());
   448	        }
   449	      }
   450	    }
   451	
   452	    Map<String, String> roots = new HashMap<>();
   453	    LinkedHashSet<String> activeRoots = new LinkedHashSet<>();
   454	    Map<String, String> anchorDuplicates = new HashMap<>();
   455	    for (String duplicateName : duplicateNames) {
   456	      String root = findFamilyRoot(duplicateName, parents, roots);
   457	      activeRoots.add(root);
   458	      anchorDuplicates.putIfAbsent(root, duplicateName);
   459	    }
   460	    this.familyIndex = new FamilyIndex(parents, roots, activeRoots, anchorDuplicates);
   461	    return this.familyIndex;
   462	  }
   463	
   464	  private static String findFamilyRoot(
   465	    String name,
   466	    Map<String, LinkedHashSet<String>> parents,
   467	    Map<String, String> roots
   468	  ) {
   469	    String cached = roots.get(name);
   470	    if (cached != null) {
   471	      return cached;
   472	    }
   473	
   474	    LinkedHashSet<String> path = new LinkedHashSet<>();
   475	    String current = name;
   476	    while (path.add(current)) {
   477	      LinkedHashSet<String> directParents = parents.get(current);
   478	      if (directParents == null || directParents.isEmpty()) {
   479	        break;
   480	      }
   481	      current = directParents.iterator().next();
   482	    }
   483	    for (String member : path) {
   484	      roots.put(member, current);
   485	    }
   486	    return current;
   487	  }
