   489	  private static boolean candidatesDiffer(List<Candidate> candidates) {
   490	    if (candidates.size() < 2) {
   491	      return false;
   492	    }
   493	    byte[] first = candidates.get(0).getBytes();
   494	    for (int index = 1; index < candidates.size(); index++) {
   495	      if (!Arrays.equals(first, candidates.get(index).getBytes())) {
   496	        return true;
   497	      }
   498	    }
   499	    return false;
   500	  }
