   502	  private void logDuplicateDecision(String name, List<Candidate> candidates, Selection selection, boolean differing) {
   503	    if (candidates.size() < 2) {
   504	      return;
   505	    }
   506	
   507	    List<String> ignored = candidates.stream()
   508	      .filter(candidate -> candidate != selection.candidate)
   509	      .map(candidate -> candidate.unit.getOriginDescription())
   510	      .toList();
   511	    String message = "Duplicate class decision: binary name " + name + ", strategy " + this.duplicateClassStrategy +
   512	      ", selected origin " + selection.candidate.unit.getOriginDescription() + ", ignored origins: " + ignored +
   513	      ", metadata family root " + selection.familyRoot;
   514	    DecompilerContext.getLogger().writeMessage(
   515	      message,
   516	      differing ? IFernflowerLogger.Severity.WARN : IFernflowerLogger.Severity.INFO
   517	    );
   518	  }
